{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_mix_score AS WITH alloc_mix AS ( SELECT branch_code, order_date, UPPER(category) AS category, COALESCE(UPPER(style), \'SNITCH\') AS style, COALESCE(UPPER(meta1), \'N/A\') AS meta1, COALESCE(UPPER(meta2), \'N/A\') AS meta2, COALESCE(UPPER(meta3), \'N/A\') AS meta3, COUNT(DISTINCT sku_group) AS actual_options FROM snitch_db.maplemonk.fresh_allocation_tagged WHERE category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), alloc_totals AS ( SELECT branch_code, order_date, SUM(actual_options) AS day_total_options, COUNT(*) AS day_total_combos FROM alloc_mix GROUP BY 1,2 ), target_mix AS ( SELECT s.branch_code, s.order_date, s.category, s.style, s.meta1, s.meta2, s.meta3, s.sales_mix_blended_pct AS raw_sales_mix_target_pct, z.zone AS store_zone, CASE WHEN z.zone = \'NORTH\' THEN \'SOUTH\' WHEN z.zone = \'SOUTH\' THEN \'NORTH\' ELSE NULL END AS other_zone FROM snitch_db.maplemonk.fresh_sales_mix_reference s LEFT JOIN snitch_db.maplemonk.store_zone_map z ON s.branch_code = z.branch_code ), joined_shipped AS ( SELECT a.branch_code, a.order_date, a.category, a.style, a.meta1, a.meta2, a.meta3, a.actual_options, tot.day_total_options, tot.day_total_combos, a.actual_options / NULLIF(tot.day_total_options, 0) AS alloc_mix_pct, COALESCE(t.raw_sales_mix_target_pct, 0) AS raw_sales_mix_target_pct, t.store_zone, t.other_zone, CASE WHEN a.category IN (\'TROUSERS\', \'JEANS\') THEN COALESCE(wp.warehouse_mix_pct, wf.warehouse_mix_pct, 0) WHEN t.store_zone IS NOT NULL THEN COALESCE(wp.warehouse_mix_pct, 0) ELSE COALESCE(wa.warehouse_mix_pct, 0) END AS raw_warehouse_mix_pct FROM alloc_mix a INNER JOIN alloc_totals tot ON a.branch_code = tot.branch_code AND a.order_date = tot.order_date LEFT JOIN target_mix t ON a.branch_code = t.branch_code AND a.order_date = t.order_date AND a.category = t.category AND a.style = t.style AND a.meta1 = t.meta1 AND a.meta2 = t.meta2 AND a.meta3 = t.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wp ON wp.order_date = a.order_date AND wp.scope = t.store_zone AND a.category = wp.category AND a.style = wp.style AND a.meta1 = wp.meta1 AND a.meta2 = wp.meta2 AND a.meta3 = wp.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wf ON wf.order_date = a.order_date AND wf.scope = t.other_zone AND a.category = wf.category AND a.style = wf.style AND a.meta1 = wf.meta1 AND a.meta2 = wf.meta2 AND a.meta3 = wf.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wa ON wa.order_date = a.order_date AND wa.scope = \'ALL\' AND a.category = wa.category AND a.style = wa.style AND a.meta1 = wa.meta1 AND a.meta2 = wa.meta2 AND a.meta3 = wa.meta3 ), batch_target_normalized AS ( SELECT *, LEAST(raw_sales_mix_target_pct, raw_warehouse_mix_pct) AS capped_target_pct, SUM(LEAST(raw_sales_mix_target_pct, raw_warehouse_mix_pct)) OVER (PARTITION BY branch_code, order_date) AS batch_target_sum, CASE WHEN raw_sales_mix_target_pct >= 0.03 AND raw_warehouse_mix_pct = 0 THEN \'Yes\' ELSE \'No\' END AS warehouse_constrained_flag FROM joined_shipped ), scored AS ( SELECT *, CASE WHEN batch_target_sum > 0 THEN capped_target_pct / batch_target_sum ELSE alloc_mix_pct END AS achievable_target_pct FROM batch_target_normalized ), with_decoupled_weight AS ( SELECT *, ABS(alloc_mix_pct - achievable_target_pct) AS mix_deviation, GREATEST(achievable_target_pct, alloc_mix_pct) AS effective_weight FROM scored ), day_rollup AS ( SELECT branch_code, order_date, SUM(mix_deviation * effective_weight) / NULLIF(SUM(effective_weight), 0) AS weighted_mix_deviation, MAX(mix_deviation) AS max_single_category_deviation, COUNT_IF(warehouse_constrained_flag = \'Yes\') AS combos_warehouse_constrained FROM with_decoupled_weight GROUP BY branch_code, order_date ) SELECT sc.*, dr.weighted_mix_deviation, dr.max_single_category_deviation, dr.combos_warehouse_constrained, CASE WHEN dr.combos_warehouse_constrained > 0 THEN \'Yes\' ELSE \'No\' END AS is_batch_warehouse_constrained, CASE WHEN sc.day_total_options < 3 THEN \'Insufficient Volume\' WHEN dr.weighted_mix_deviation IS NULL THEN \'No Data\' WHEN dr.weighted_mix_deviation <= 0.15 AND dr.max_single_category_deviation > 0.35 THEN \'Okay\' WHEN dr.weighted_mix_deviation <= 0.15 THEN \'Perfect\' WHEN dr.weighted_mix_deviation <= 0.30 THEN \'Okay\' ELSE \'Poor\' END AS mix_score FROM with_decoupled_weight sc LEFT JOIN day_rollup dr ON sc.branch_code = dr.branch_code AND sc.order_date = dr.order_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            